(()=>{
  "use strict";
  const expansion=window.ScienceExpansion;if(!expansion)return;
  const W=(en,meaning,example)=>({en,vi:"",meaning,pos:"science term",example});
  const Q=(prompt,choices,right,why)=>({type:"mcq",prompt,choices,right,why});
  const backgrounds={earth:"assets/science-earth-lab-v1.png",ice:"assets/science-winter-review-v1.png",water:"assets/science-wetland-effects-v2.png",space:"assets/moon-bio-lab-v1.png",micro:"assets/microscopic-world-v1.png",energy:"assets/science-earth-lab-thumb-v2.png",life:"assets/garden-room-v1.png"};
  const groups=[
    {grade:4,bigIdea:3,idea:"Slow and rapid processes—from erosion to earthquakes—shape and reshape Earth's surface.",weeks:[
      ["How was the Grand Canyon formed?","Weathering loosened rock while the Colorado River and gravity carried material away over millions of years.",["Rock layers record different chapters of the region's geologic past.","Rain, ice, plant roots and temperature changes break rock into smaller pieces.","Flowing water moves sediment and cuts downward through uplifted land.","Dams and changing river flow can alter erosion and habitats today."],["weathering|the breaking of rock in place","erosion|the movement of weathered material","sediment|small pieces carried by wind, water or ice","uplift|the raising of Earth's crust"],"earth"],
      ["Do glaciers really move?","Glaciers flow slowly downhill under their own weight, eroding rock and carrying debris.",["Snow that survives many seasons is compressed into dense glacial ice.","Ice deforms and slides, so a glacier can move even when it looks still.","Rock frozen into the base scrapes valleys and transports sediment.","Melting glaciers leave ridges called moraines and release meltwater."],["glacier|a large moving mass of land ice","moraine|a ridge of debris left by a glacier","meltwater|water released by melting snow or ice","valley|low land between hills or mountains"],"ice"],
      ["What makes a volcano erupt?","Rising magma contains gases that expand as pressure falls, sometimes forcing molten rock through vents.",["Heat inside Earth can melt rock and form magma below the surface.","Magma can rise because it is less dense than surrounding solid rock.","Trapped gases expand as magma approaches the surface.","Runny lava may flow quietly, while gas-rich sticky magma can erupt explosively."],["magma|molten rock below Earth's surface","lava|molten rock at Earth's surface","vent|an opening through which volcanic material escapes","pressure|force spread over an area"],"earth"],
      ["What causes earthquakes?","Earthquakes occur when stressed rock suddenly slips along a fault and releases energy as seismic waves.",["Tectonic plates move slowly but their edges can lock together.","Stress builds until rock breaks or slips along a fault.","Seismic waves spread outward from the underground focus.","Scientists use seismometers and several stations to locate an earthquake."],["fault|a break in Earth's crust where rocks move","seismic wave|energy that travels through Earth","focus|the underground point where an earthquake starts","seismometer|an instrument that records ground motion"],"earth"]]},
    {grade:4,bigIdea:4,idea:"The properties of rocks and minerals reflect the processes that formed them.",weeks:[
      ["What's the difference between a rock and a mineral?","A mineral has a definite composition and crystal structure; a rock is a mixture of one or more minerals.",["Minerals are naturally occurring solids with orderly crystal structures.","Color alone can mislead, so hardness, streak and luster help identify a mineral.","Most rocks contain grains of several different minerals.","Texture and mineral grains provide clues to how a rock formed."],["mineral|a natural solid with a definite composition and crystal structure","rock|a natural solid mixture of minerals or other material","hardness|resistance to scratching","luster|the way a surface reflects light"],"earth"],
      ["Where do rocks come from?","Igneous, sedimentary and metamorphic rocks form and change through the rock cycle.",["Cooling magma or lava forms igneous rock.","Layers of sediment can compact and cement into sedimentary rock.","Heat and pressure change existing rock into metamorphic rock without fully melting it.","Uplift, weathering, burial, melting and cooling keep the rock cycle moving."],["igneous|rock formed when molten material cools","sedimentary|rock formed from compacted or cemented sediment","metamorphic|rock changed by heat and pressure","rock cycle|the processes that transform rocks"],"earth"],
      ["Are some rocks valuable?","Rocks are valuable when they contain useful minerals, fuels or gemstones, but supplies must be managed responsibly.",["Ore contains enough of a useful mineral or metal to make extraction practical.","Coal is a fossil fuel formed from ancient organic material.","Gemstones are valued for beauty, durability and rarity.","Reusing metals and conserving materials reduce the need for new mining."],["ore|rock containing a useful material that can be extracted","extract|to remove a useful substance","fossil fuel|fuel formed from ancient organisms","conserve|to protect a resource from waste"],"earth"],
      ["Do all rocks come from Earth?","Meteorites are rocks from space, and samples from the Moon and asteroids help scientists compare planetary histories.",["Most meteors burn in the atmosphere, but a fragment reaching the ground is a meteorite.","Many meteorites are pieces of asteroids left from early solar-system history.","Moon rocks collected by missions reveal volcanic plains and impact history.","Chemical similarities among samples help scientists test ideas about how worlds formed."],["meteor|a streak of light from space material heating in the atmosphere","meteorite|space rock that reaches the ground","asteroid|a rocky object orbiting the Sun","lunar|related to the Moon"],"space"]]},
    {grade:4,bigIdea:5,idea:"Electrical energy can be converted into heat, light, sound and motion.",weeks:[
      ["How do toasters work?","A toaster sends electric current through a high-resistance wire, changing electrical energy into heat.",["A closed circuit allows electric current to move through the toaster.","Thin heating wire resists the current and becomes hot.","The hot wire radiates thermal energy that browns the bread.","A timer or thermostat opens the circuit and releases the toast."],["circuit|a complete path for electric current","current|the flow of electric charge","resistance|opposition to electric current","thermal energy|energy associated with particle motion"],"energy"],
      ["What lights a digital clock?","A digital clock converts electrical energy into controlled light patterns while an electronic oscillator keeps time.",["A battery or outlet supplies electrical energy to the clock circuit.","A repeating electronic signal divides time into equal intervals.","The circuit sends current to selected display segments.","Light-emitting diodes convert electrical energy into visible light efficiently."],["digital|using separate numerical values or signals","display|a device that shows information","diode|a component that lets current move mainly one way","oscillator|a system producing a regular repeating signal"],"energy"],
      ["How do hearing aids help people hear?","A hearing aid changes sound into an electrical signal, processes it, and changes it back into amplified sound.",["A microphone converts sound vibrations into an electrical signal.","A processor adjusts selected frequencies instead of simply making everything louder.","An amplifier increases the strength of the processed signal.","A tiny speaker converts the signal back into sound near the ear."],["microphone|a device that changes sound into an electrical signal","amplify|to increase signal strength","frequency|the rate of a vibration","speaker|a device that changes an electrical signal into sound"],"energy"],
      ["How do electric cars work?","Batteries supply current to a motor, where magnetic forces convert electrical energy into wheel motion.",["Rechargeable cells store chemical energy and deliver electrical energy.","Current in motor coils creates an electromagnet.","Forces between magnetic fields turn the motor shaft.","A controller adjusts current, while regenerative braking can return some energy to the battery."],["electric motor|a device that converts electrical energy into motion","electromagnet|a magnet produced by electric current","controller|a device that regulates power","mechanical energy|energy of motion or position"],"energy"]]},
    {grade:4,bigIdea:6,idea:"People invented machines to make work easier.",weeks:[
      ["Why do some building entrances have ramps?","A ramp is an inclined plane that reduces the force needed to raise a load by spreading the work over a longer distance.",["Work involves applying a force through a distance.","A gentle ramp requires less upward force than lifting straight up.","The trade-off is moving through a longer distance.","Ramps improve access for wheels, carts and people with different mobility needs."],["inclined plane|a sloping surface used to raise or lower objects","work|force applied through a distance","force|a push or pull","mechanical advantage|how much a machine multiplies force"],"energy"],
      ["What's the difference between a nail and a screw?","A nail is driven by force and friction; a screw wraps an inclined plane around a shaft to grip material.",["A nail's point acts like a wedge that separates material.","Friction along a nail helps hold joined pieces together.","A screw thread is an inclined plane wrapped around a cylinder.","Turning a screw trades a longer path for greater holding force and control."],["wedge|a simple machine with sloping sides","screw|an inclined plane wrapped around a cylinder","thread|the spiral ridge on a screw","friction|a force resisting sliding surfaces"],"energy"],
      ["How do elevators work?","Elevators use motors, cables, pulleys and counterweights to move a car safely between floors.",["A motor turns a grooved pulley called a sheave.","Strong cables connect the car and a counterweight over the sheave.","The counterweight reduces the force the motor must provide.","Brakes, doors and speed sensors form important safety systems."],["pulley|a wheel with a groove for a rope or cable","counterweight|a balancing mass","cable|a strong bundle used to pull or support","brake|a device that slows or stops motion"],"energy"],
      ["How does a wheelbarrow make work easier?","A wheelbarrow combines a lever with a wheel and axle to move a heavy load with less effort.",["The wheel acts as the fulcrum of a second-class lever.","The load sits between the fulcrum and the effort at the handles.","Long handles provide mechanical advantage when lifting.","The wheel and axle reduce sliding friction while the load moves."],["lever|a rigid bar that turns around a fulcrum","fulcrum|the pivot point of a lever","wheel and axle|a wheel fixed to a smaller shaft","load|the object or resistance moved by a machine"],"energy"]]},
    {grade:5,bigIdea:3,idea:"Water covers most of Earth's surface and circulates between ocean, atmosphere and land.",weeks:[
      ["Do we really drink the same water that dinosaurs did?","Earth's water is continually recycled, so many water molecules have moved through oceans, air, rock and organisms for immense periods.",["Sunlight powers evaporation from oceans, lakes and soil.","Cooling water vapor condenses into clouds.","Precipitation returns water to land and oceans.","Runoff, groundwater and living things move water through many reservoirs before the cycle repeats."],["evaporation|liquid water changing to water vapor","condensation|water vapor changing to liquid droplets","precipitation|water falling from clouds","water cycle|the continuous movement of water on Earth"],"water"],
      ["Why don't rivers and lakes soak into the ground?","Some water infiltrates soil, while saturated ground, clay and solid rock slow further movement and allow surface water to remain.",["Pore spaces let water infiltrate permeable soil and rock.","Clay has tiny spaces that slow water movement.","Below the water table, available spaces are already filled with groundwater.","Rivers and lakes persist when inflow balances seepage, evaporation and outflow."],["infiltration|water entering soil or rock","permeable|allowing water to pass through","water table|the upper level of saturated ground","groundwater|water stored beneath Earth's surface"],"water"],
      ["What makes deserts so dry?","Deserts form where atmospheric circulation, mountain rain shadows or cold currents limit precipitation.",["Dry sinking air near 30 degrees latitude discourages cloud formation.","Mountains force moist air upward, leaving drier air on the leeward side.","Cold ocean currents can stabilize air and reduce rainfall along some coasts.","Desert organisms conserve water and avoid extreme daytime heat."],["desert|a region receiving very little precipitation","rain shadow|a dry area on the sheltered side of a mountain","humidity|water vapor in the air","adaptation|a trait that helps survival"],"earth"],
      ["Can we run out of water?","Earth will not lose its water cycle, but communities can run short of clean accessible freshwater.",["Most of Earth's water is salty ocean water.","Much freshwater is frozen or stored deep underground.","Pollution and overuse can make local supplies unsafe or unavailable.","Conservation, watershed protection, reuse and treatment help secure water supplies."],["freshwater|water containing little dissolved salt","watershed|land draining to the same body of water","conservation|careful use and protection of resources","treatment|processes that make water safer to use"],"water"]]},
    {grade:5,bigIdea:4,idea:"Gravity keeps planets in orbit around the Sun and the Moon in orbit around Earth.",weeks:[
      ["Why do we weigh more on Earth than on the moon?","Weight depends on gravitational pull; the Moon has much less mass than Earth, so it pulls the same object less strongly.",["Mass measures how much matter an object contains and does not change with location.","Weight is the gravitational force acting on that mass.","Earth's greater mass produces a stronger surface gravitational pull than the Moon's.","An astronaut's mass stays the same on both worlds, but the measured weight changes."],["mass|the amount of matter in an object","weight|the force of gravity on an object","gravity|attraction between masses","newton|a unit used to measure force"],"space"],
      ["What causes ocean tides?","The Moon's gravity, with a smaller contribution from the Sun, produces regularly changing ocean levels as Earth rotates.",["The Moon pulls more strongly on the near side of Earth than the far side.","This difference helps produce two broad tidal bulges.","Coasts rotate through higher and lower water levels.","Sun, Moon and Earth alignment produces larger spring tides, while right-angle positions produce smaller neap tides."],["tide|the regular rise and fall of ocean level","tidal bulge|a broad region where ocean water is raised","spring tide|a tide with a larger range","neap tide|a tide with a smaller range"],"space"],
      ["Why are planets round?","Gravity pulls matter toward a large body's center, smoothing large planets and moons into nearly spherical shapes.",["Every part of a massive body attracts every other part.","When a young world is hot or deformable, material can move toward the center.","A sphere balances inward gravitational pull in all directions.","Rotation can make a planet bulge slightly at the equator, so it is not a perfect sphere."],["sphere|a three-dimensional round shape","center of mass|the balance point of an object's mass","rotation|spinning around an axis","equator|the line around a world's widest middle"],"space"],
      ["Why don't planets crash into each other?","A planet's forward motion and the Sun's gravity combine to create a stable orbit rather than a straight fall.",["Inertia would carry a moving planet along a straight path.","The Sun's gravity continually bends that path inward.","The result is an elliptical orbit around the Sun.","Planets occupy different orbits, and their predictable motions usually keep them far apart."],["orbit|the curved path of one object around another","inertia|the tendency to keep the same motion","elliptical|shaped like a stretched circle","solar system|the Sun and objects bound to it by gravity"],"space"]]},
    {grade:5,bigIdea:5,idea:"Heat flows from warmer objects to cooler ones until they reach thermal equilibrium.",weeks:[
      ["How does a thermometer work?","A thermometer uses a property that changes predictably with temperature and displays that change on a calibrated scale.",["Particles generally move faster as temperature rises.","A liquid thermometer's fluid expands and rises in a narrow tube when warmed.","Digital thermometers use sensors whose electrical properties change with temperature.","Calibration connects a measured change to standard temperature units."],["temperature|a measure related to average particle motion","expand|to increase in volume","calibrate|to mark or adjust a measuring instrument","sensor|a device that detects a physical change"],"energy"],
      ["How does a microwave oven cook food?","Microwave energy makes polar molecules, especially water, rotate and collide, increasing thermal energy in the food.",["A magnetron produces microwaves inside the oven.","An electric field reverses rapidly and influences polar molecules.","Molecular motion and collisions transfer energy through the food.","Uneven composition and depth can create hot and cool spots, so standing time helps heat spread."],["microwave|a type of electromagnetic wave","molecule|two or more atoms chemically joined","thermal energy|energy associated with particle motion","conduction|heat transfer through direct contact"],"energy"],
      ["What causes hurricanes?","Hurricanes grow over very warm ocean water when moist rising air releases heat and organized winds strengthen around low pressure.",["Warm seawater supplies water vapor and energy.","Condensation in towering clouds releases heat that fuels more rising air.","Air flows toward lower pressure and Earth's rotation helps the storm spin.","Cool water, dry air or land cuts off energy and weakens the storm."],["hurricane|a powerful rotating tropical storm","low pressure|a region where air pressure is lower than nearby","condense|to change from gas to liquid","storm surge|ocean water pushed ashore by a storm"],"water"],
      ["How does a thermos work?","A thermos slows conduction, convection and radiation so its contents change temperature more slowly.",["A vacuum between double walls leaves few particles to conduct heat.","A sealed lid reduces convection and evaporation.","Shiny surfaces reflect thermal radiation.","Insulation does not create cold or heat; it slows energy transfer in either direction."],["insulator|a material that slows energy transfer","conduction|heat transfer through particle collisions","convection|heat transfer by moving fluid","radiation|energy transfer by electromagnetic waves"],"energy"]]},
    {grade:5,bigIdea:6,idea:"A chemical reaction forms substances with properties different from the starting materials.",weeks:[
      ["What puts the fizz in soda?","Carbon dioxide dissolved under pressure escapes as bubbles when a soda container is opened.",["Factories force carbon dioxide gas into liquid under high pressure.","A closed container keeps more gas dissolved.","Opening lowers the pressure, so gas leaves the liquid.","Scratches, ice and other nucleation sites help bubbles begin forming."],["carbon dioxide|a gas with one carbon and two oxygen atoms","dissolve|to mix uniformly into a liquid","pressure|force spread over an area","nucleation site|a place where a bubble can begin"],"energy"],
      ["Why does metal rust?","Iron rusts when it reacts with oxygen in the presence of water, forming new iron oxide compounds.",["Rusting is an oxidation reaction that changes iron atoms.","Water helps ions move and allows the reaction to continue.","Salt speeds corrosion by improving electrical conduction in the water.","Paint, oil, plating or sacrificial metals can separate iron from water and oxygen."],["rust|iron oxide produced by corrosion","oxidation|a reaction involving electron loss, often with oxygen","corrosion|gradual chemical damage to a material","coating|a protective layer on a surface"],"earth"],
      ["Why do batteries die?","A battery stops delivering useful current when reactants are depleted or internal changes prevent the chemical reaction from continuing effectively.",["Separated chemicals at two electrodes store potential chemical energy.","A reaction pushes electrons through an external circuit.","Ions move through an electrolyte to balance charge inside the cell.","Rechargeable batteries use outside electrical energy to reverse many reaction changes."],["electrode|a conductor where a battery reaction occurs","electrolyte|a substance with mobile ions","chemical energy|energy stored in chemical bonds","rechargeable|able to restore stored energy using electricity"],"energy"],
      ["Why can't you light a match more than once?","A match burns only once because its limited fuel and reactive coating are converted into new products.",["Friction supplies the activation energy needed to start the reaction.","Chemicals in the match head ignite and heat the wooden fuel.","Combustion uses oxygen and releases heat and light.","After the reactants become gases and ash, the original fuel cannot simply be used again."],["combustion|a reaction with oxygen that releases energy","reactant|a starting substance in a reaction","product|a new substance formed by a reaction","activation energy|the energy needed to begin a reaction"],"energy"]]},
    {grade:6,bigIdea:3,idea:"Earth's axial tilt and solar energy affect seasons and weather patterns.",weeks:[
      ["What causes the weather?","Uneven solar heating drives changing air pressure, winds, clouds and precipitation in the atmosphere.",["Land, water and ice absorb and release solar energy at different rates.","Warm air expands and rises, while cooler denser air sinks.","Water evaporates, condenses into clouds and may fall as precipitation.","Moving air masses and fronts create many short-term weather changes."],["atmosphere|the layer of gases around Earth","air pressure|the force of air on a surface","front|a boundary between air masses","precipitation|water falling from clouds"],"water"],
      ["Why don't hurricanes happen at the equator?","Hurricanes rarely form exactly at the equator because the Coriolis effect is too weak there to organize broad rotation.",["Warm tropical water and moist unstable air can supply storm energy.","Earth's rotation deflects moving air through the Coriolis effect.","That deflection is zero at the equator and strengthens with latitude.","Tropical cyclones usually begin several degrees north or south where rotation can organize."],["Coriolis effect|the apparent deflection of motion on a rotating Earth","equator|the line at zero degrees latitude","tropical cyclone|an organized rotating tropical storm","latitude|distance north or south of the equator"],"water"],
      ["Why are the North and South Poles so cold?","Polar regions receive low-angle sunlight spread over a large area, and bright ice reflects much of that energy.",["Earth's curvature makes sunlight strike the poles at a shallow angle.","Low-angle rays travel through more atmosphere and spread their energy.","Snow and ice have high albedo and reflect much incoming sunlight.","Long winter darkness allows extended cooling."],["solar energy|energy Earth receives from the Sun","albedo|the fraction of light a surface reflects","curvature|the amount a surface bends","horizon|the apparent line where land or sea meets sky"],"ice"],
      ["Are the seasons reversed on the other side of the world?","The hemispheres have opposite seasons because Earth's tilted axis points one hemisphere toward the Sun while the other points away.",["Earth's axis is tilted about 23.5 degrees relative to its orbit.","A hemisphere tilted sunward receives more direct light and longer days.","Six months later the same hemisphere is tilted away and receives less solar energy.","Distance from the Sun is not the main cause of seasons."],["axis|an imaginary line around which Earth rotates","hemisphere|half of Earth","solstice|the time of greatest or least seasonal daylight","equinox|the time when day and night are nearly equal"],"space"]]},
    {grade:6,bigIdea:4,idea:"Earth has a crust, mantle and core; plates in the crust move slowly across the surface.",weeks:[
      ["Why do the continents look like they fit together?","Matching coastlines, fossils, rocks and ancient climate evidence show that continents were once joined and later moved apart.",["South America and Africa have complementary continental margins.","Matching fossils occur on continents now separated by oceans.","Rock belts and mountain chains continue across continental boundaries.","Seafloor spreading and plate tectonics explain how the continents move."],["continental drift|the long-term movement of continents","fossil|preserved evidence of past life","plate tectonics|the theory of moving lithospheric plates","seafloor spreading|formation of new ocean crust at ridges"],"earth"],
      ["How do scientists know what is inside Earth?","Scientists infer Earth's layered interior from seismic waves, density, meteorites, magnetic fields and experiments.",["P waves change speed and direction as materials change.","S waves do not travel through the liquid outer core.","Earth's average density requires denser material deep inside.","High-pressure experiments test how minerals behave in the mantle and core."],["crust|Earth's thin outer solid layer","mantle|the thick hot rock layer below the crust","core|Earth's central metallic region","seismic wave|energy traveling through Earth"],"earth"],
      ["What happens when two continents collide?","Continental collision crumples and thickens buoyant crust, building mountains and causing earthquakes.",["Ocean crust may be subducted before two continents meet.","Continental crust resists sinking because it is relatively buoyant.","Compression folds, faults and uplifts great masses of rock.","The Himalaya continues to rise as India and Eurasia converge."],["collision boundary|a place where tectonic plates move together","subduction|one plate sinking beneath another","compression|forces squeezing material together","mountain range|a connected group of mountains"],"earth"],
      ["What will Earth's surface look like in the future?","Plate motions measured today let scientists estimate future geography, although exact continents and oceans remain uncertain.",["GPS stations measure plate movement of centimeters per year.","Atlantic seafloor continues spreading at the Mid-Atlantic Ridge.","Subduction closes some ocean basins while rifting opens others.","Over tens of millions of years, continents may assemble into another supercontinent."],["GPS|satellite-based position measurement","rift|a region where crust pulls apart","converge|to move toward one another","supercontinent|a landmass containing most continents"],"earth"]]},
    {grade:6,bigIdea:5,idea:"Matter is made of atoms, and different arrangements of atoms compose all substances.",weeks:[
      ["What do atoms look like?","Atoms have a tiny nucleus of protons and neutrons surrounded by a probabilistic cloud of electrons.",["The nucleus contains nearly all of an atom's mass.","Protons carry positive charge and electrons carry negative charge.","Electrons occupy regions called orbitals rather than fixed miniature-planet paths.","Atoms are too small for visible-light microscopes, so models and instruments reveal their structure."],["atom|the smallest unit retaining an element's properties","nucleus|the dense center of an atom","electron|a negatively charged subatomic particle","orbital|a region where an electron is likely to be found"],"micro"],
      ["What is the periodic table?","The periodic table organizes elements by atomic number so repeating patterns in chemical properties become visible.",["Atomic number equals the number of protons in an atom.","Rows are periods and columns are groups.","Elements in a group often have similar outer-electron behavior.","Metals, nonmetals and metalloids occupy broad regions with characteristic properties."],["element|a substance made of one kind of atom","atomic number|the number of protons in an atom","period|a horizontal row of the periodic table","group|a vertical column of related elements"],"micro"],
      ["What is water made of?","Each water molecule contains two hydrogen atoms covalently bonded to one oxygen atom, giving it a polar shape.",["The formula H2O records the ratio of hydrogen to oxygen atoms.","Atoms share electrons in covalent bonds within a molecule.","Uneven charge makes water molecules attract one another through hydrogen bonding.","Polarity helps water dissolve many ionic and polar substances."],["molecule|a group of atoms chemically bonded","covalent bond|a bond formed by sharing electrons","polar|having an uneven distribution of charge","solution|a uniform mixture of dissolved substances"],"water"],
      ["How are living things different from nonliving things?","Living things have organized cells, genetic information and self-regulated chemical systems, even though they use the same kinds of atoms as nonliving matter.",["Cells provide boundaries and organized machinery for life processes.","DNA stores information used for growth and reproduction.","Metabolism transforms matter and energy through many controlled reactions.","Viruses show why the boundary is complex: they evolve but require host cells to reproduce."],["cell|the basic organized unit of life","DNA|a molecule carrying hereditary information","metabolism|the chemical reactions of an organism","organic compound|a carbon-based compound common in living systems"],"micro"]]},
    {grade:6,bigIdea:6,idea:"Energy can be mechanical, electrical, thermal or chemical; light, sound and heat are common results.",weeks:[
      ["How do windmills make electricity?","Wind turbines convert moving air's kinetic energy into rotation and then electrical energy by electromagnetic induction.",["Wind transfers kinetic energy to shaped turbine blades.","A rotating shaft carries mechanical energy into a generator.","Moving magnetic fields near wire coils induce electric current.","Power electronics and transformers prepare the electricity for the grid."],["kinetic energy|energy of motion","turbine|a rotor turned by moving fluid","generator|a device converting motion into electrical energy","electromagnetic induction|production of voltage by a changing magnetic field"],"energy"],
      ["What makes popcorn pop?","Heating turns water inside a sealed kernel into vapor until pressure bursts the hull and expands the softened starch.",["A popcorn kernel has a strong moisture-resistant outer hull.","Thermal energy makes internal water molecules move faster and vaporize.","Pressure rises because vapor cannot easily escape.","When the hull breaks, pressure drops and hot starch expands and cools into foam."],["hull|the hard outer covering of a seed","water vapor|water in gas form","pressure|force spread over an area","thermal energy|energy associated with particle motion"],"energy"],
      ["What makes fireflies glow?","Fireflies use an enzyme-controlled bioluminescent reaction that converts chemical energy into visible light with little heat.",["Luciferin reacts with oxygen in light-producing cells.","The enzyme luciferase speeds the reaction.","ATP supplies chemical energy and the reaction emits photons.","Species-specific flash patterns help adults communicate with potential mates."],["bioluminescence|light made by a living organism","enzyme|a biological catalyst","chemical energy|energy stored in chemical bonds","photon|a packet of light energy"],"life"],
      ["How do fireworks work?","Fireworks use controlled chemical reactions to launch shells, burst charges and excite metal compounds that emit colored light.",["Burning propellant produces expanding gas that launches a shell.","A timed fuse ignites a burst charge high above the ground.","Arranged pellets called stars create the pattern and contain color-producing chemicals.","Excited atoms emit characteristic wavelengths as electrons return to lower energy states."],["propellant|material producing gas to create motion","fuse|a timed path that carries flame","spectrum|the range of wavelengths of light","chemical reaction|a process rearranging atoms into new substances"],"energy"]]}
  ];
  const ids={4:100,5:200,6:300};
  groups.forEach(group=>group.weeks.forEach((raw,weekIndex)=>{
    const [title,answer,facts,termDefs,bg]=raw,number=ids[group.grade]++;
    const terms=termDefs.map((entry,index)=>{const [en,meaning]=entry.split("|");return W(en,meaning,`${en} helps explain ${title.toLowerCase()}`)});
    const days=[null,...facts.map((fact,index)=>{
      const focus=terms[index%terms.length],other=terms[(index+1)%terms.length];
      const related=terms.map(term=>`${term.en} means ${term.meaning}`).join("; "),openers=["The book begins with this evidence:","The next reading traces a cause-and-effect step:","This lesson examines another piece of evidence:","The final learning day connects the week's evidence:"];
      const story=`${openers[index]} ${fact} Key vocabulary for reading the explanation: ${related}. This information helps answer “${title}” because ${answer.charAt(0).toLowerCase()+answer.slice(1)}`;
      return{day:index+1,title:["Observe the system","Trace the process","Test the evidence","Connect the explanation"][index],short:["First Evidence","Cause and Effect","Model Check","Science Conclusion"][index],image:backgrounds[bg],icon:["🔎","🧭","🧪","💡"][index],guideLine:["Begin with a careful observation.","Follow matter, energy or force through the system.","Use the model to test the explanation.","Combine all evidence into one conclusion."][index],story,words:[focus,other,terms[(index+2)%terms.length]],questions:[Q("Which statement is supported by today's evidence?",[fact,"The process happens without matter, energy or force.","Scientific explanations do not need observations."],0,fact),Q(`Which conclusion best answers “${title}” ?`,[answer,"The evidence shows that nothing changes.","Only one isolated word is needed to explain the system."],0,answer),Q(`What does “${focus.en}” mean?`,[focus.meaning,other.meaning,"a detail unrelated to this investigation"],0,`${focus.en} means ${focus.meaning}.`)]};
    })];
    const firstPage=8+(group.bigIdea-1)*30+weekIndex*6;
    expansion.weeks[number]={number,title,subtitle:`Grade ${group.grade} · Big Idea ${group.bigIdea} · Week ${weekIndex+1}`,guide:"Daily Science",hero:backgrounds[bg],days,source:{grade:group.grade,bigIdea:group.bigIdea,bookWeek:weekIndex+1,pages:`${firstPage}-${firstPage+5}`,review:false,publisher:"Evan-Moor Daily Science"},overview:facts};
  }));
})();
